package rw.umurava.essentials;

import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import rw.umurava.community.CommunityMembershipRepository;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.UUID;

@Service
public class EssentialServicesService {
 private static final String ACTIVE="ACTIVE";
 private final JdbcTemplate jdbc; private final CommunityMembershipRepository memberships;
 public EssentialServicesService(JdbcTemplate jdbc,CommunityMembershipRepository memberships){this.jdbc=jdbc;this.memberships=memberships;}
 @Transactional(readOnly=true) public List<java.util.Map<String,Object>> food(UUID actor,UUID community){member(actor,community);return jdbc.queryForList("SELECT id,food_name,food_category,quantity,unit,expiry_date,storage_location,CASE WHEN expiry_date<CURRENT_DATE THEN 'EXPIRED' ELSE status END AS display_status,created_at FROM food_batches WHERE community_id=? ORDER BY expiry_date NULLS LAST,food_name",community);}
 @Transactional public java.util.Map<String,Object> addFood(UUID actor,UUID community,String name,String category,BigDecimal quantity,String unit,LocalDate expiry,String location){manager(actor,community);if(quantity.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity cannot be negative");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO food_batches(id,community_id,food_name,food_category,quantity,unit,expiry_date,storage_location,recorded_by) VALUES (?,?,?,?,?,?,?,?,?)",id,community,name.trim(),category.trim(),quantity,unit.trim(),expiry,location,actor);return jdbc.queryForMap("SELECT id,food_name,food_category,quantity,unit,expiry_date,storage_location,status,created_at FROM food_batches WHERE id=?",id);}
 @Transactional(readOnly=true) public List<java.util.Map<String,Object>> water(UUID actor,UUID community){member(actor,community);return jdbc.queryForList("SELECT id,name,source_type,estimated_liters,potable_status,latitude,longitude,status,created_at FROM water_sources WHERE community_id=? ORDER BY name",community);}
 @Transactional public java.util.Map<String,Object> addWater(UUID actor,UUID community,String name,String type,BigDecimal liters,Double lat,Double lon){manager(actor,community);if(liters!=null&&liters.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Estimated volume cannot be negative");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO water_sources(id,community_id,name,source_type,estimated_liters,latitude,longitude,recorded_by) VALUES (?,?,?,?,?,?,?,?)",id,community,name.trim(),type.trim(),liters,lat,lon,actor);return jdbc.queryForMap("SELECT id,name,source_type,estimated_liters,potable_status,latitude,longitude,status FROM water_sources WHERE id=?",id);}
 @Transactional public java.util.Map<String,Object> addWaterTest(UUID actor,UUID community,UUID source,BigDecimal ph,BigDecimal turbidity,Boolean ecoli,String notes){manager(actor,community);Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM water_sources WHERE id=? AND community_id=?",Integer.class,source,community);if(exists==null||exists==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Water source not found in this community");if(ph!=null&&(ph.signum()<0||ph.compareTo(new BigDecimal("14"))>0))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"pH must be between 0 and 14");if(turbidity!=null&&turbidity.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Turbidity cannot be negative");String result=(Boolean.TRUE.equals(ecoli)||(ph!=null&&(ph.compareTo(new BigDecimal("6.5"))<0||ph.compareTo(new BigDecimal("8.5"))>0))||(turbidity!=null&&turbidity.compareTo(new BigDecimal("5"))>0))?"REVIEW_REQUIRED":"NO_FLAG_DETECTED";UUID id=UUID.randomUUID();jdbc.update("INSERT INTO water_quality_tests(id,community_id,source_id,tested_by,ph_value,turbidity_ntu,ecoli_detected,screening_result,notes) VALUES (?,?,?,?,?,?,?,?,?)",id,community,source,actor,ph,turbidity,ecoli,result,notes);jdbc.update("UPDATE water_sources SET potable_status='TEST_RECORDED',updated_at=NOW() WHERE id=?",source);return jdbc.queryForMap("SELECT id,source_id,ph_value,turbidity_ntu,ecoli_detected,screening_result,notes,tested_at FROM water_quality_tests WHERE id=?",id);}
 @Transactional(readOnly=true) public List<java.util.Map<String,Object>> tests(UUID actor,UUID community,UUID source){member(actor,community);return jdbc.queryForList("SELECT id,source_id,ph_value,turbidity_ntu,ecoli_detected,screening_result,notes,tested_at FROM water_quality_tests WHERE community_id=? AND source_id=? ORDER BY tested_at DESC",community,source);}
 @Transactional(readOnly=true) public List<java.util.Map<String,Object>> energy(UUID actor,UUID community){member(actor,community);return jdbc.queryForList("SELECT id,name,asset_type,capacity_kwh,current_output_kw,operational_status,location_description,last_service_at FROM energy_assets WHERE community_id=? ORDER BY name",community);}
 @Transactional public java.util.Map<String,Object> addEnergy(UUID actor,UUID community,String name,String type,BigDecimal capacity,BigDecimal output,String status,String location){manager(actor,community);if(capacity!=null&&capacity.signum()<0||output!=null&&output.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Energy values cannot be negative");if(!Set.of("OPERATIONAL","MAINTENANCE","OUT_OF_SERVICE","UNKNOWN").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid operational status");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO energy_assets(id,community_id,name,asset_type,capacity_kwh,current_output_kw,operational_status,location_description,recorded_by) VALUES (?,?,?,?,?,?,?,?,?)",id,community,name.trim(),type.trim(),capacity,output,status,location,actor);return jdbc.queryForMap("SELECT id,name,asset_type,capacity_kwh,current_output_kw,operational_status,location_description FROM energy_assets WHERE id=?",id);}
 private void member(UUID user,UUID community){if(!memberships.existsByUserIdAndCommunityIdAndStatus(user,community,ACTIVE))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Active community membership required");}
 private void manager(UUID user,UUID community){if(!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,"COMMUNITY_ADMIN",ACTIVE)&&!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,"RESOURCE_MANAGER",ACTIVE))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Resource manager or community administrator required");}
}
